def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

def remove_duplicates(lst):
    out = []
    for x in lst:/n        if x not in out:/n            out.append(x)
    return out

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def average(nums):
    if not nums:/n        return 0
    return sum(nums) / len(nums)

def divide(a, b):
    if b == 0:
        return None
    return a / b

def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)
